// Product photography lives in /public/images/phones/<phoneId>/<colour-slug>.webp
// (1000px) plus <colour-slug>-sm.webp (480px). The manifest is generated by
// scripts/build-image-manifest.mjs so we never reference a missing file.
import manifest from '../data/imageManifest.json'

export const slugify = (s = '') =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')

const build = (phoneId, slug) => ({
  src: `/images/phones/${phoneId}/${slug}.webp`,
  srcSm: `/images/phones/${phoneId}/${slug}-sm.webp`,
})

/** Main image for a phone in a colour (falls back to any available colour). */
export function phoneImage(phoneId, colorName) {
  const m = manifest[phoneId]
  if (!m?.colors.length) return null
  const slug = slugify(colorName)
  return build(phoneId, m.colors.includes(slug) ? slug : m.colors[0])
}

/**
 * Gallery for the product page: the colour image first, then extra angles.
 * Extra angles are only shot in the phone's first colour, so we only show them
 * for that colour to avoid showing the wrong finish.
 */
export function phoneGallery(phone, colorName) {
  const main = phoneImage(phone.id, colorName)
  if (!main) return []
  const extras =
    slugify(colorName) === slugify(phone.colors[0].name)
      ? (manifest[phone.id]?.gallery || []).map((g) => build(phone.id, g))
      : []
  return [main, ...extras]
}
